import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>

#define BATCH_SIZE 2
#define NUM_HEADS 32
#define SEQ_LEN 256
#define HEAD_DIM 1024
#define THREADS 256

__global__ void sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O
) {
    __shared__ float q_sh[HEAD_DIM];
    __shared__ float out_sh[HEAD_DIM];
    __shared__ float scores[SEQ_LEN];
    __shared__ float red[THREADS];
    __shared__ float m_sh;
    __shared__ float sum_sh;

    const int tid = threadIdx.x;
    const int bh = blockIdx.x;   // batch * head index
    const int row = blockIdx.y;  // query row

    const size_t bh_base = (size_t)bh * SEQ_LEN * HEAD_DIM;
    const size_t q_base = bh_base + (size_t)row * HEAD_DIM;

    const float scale = rsqrtf((float)HEAD_DIM);

    for (int d = tid; d < HEAD_DIM; d += THREADS) {
        q_sh[d] = __half2float(Q[q_base + d]);
        out_sh[d] = 0.0f;
    }
    __syncthreads();

    // Compute all scaled scores for this query row.
    for (int j = 0; j < SEQ_LEN; ++j) {
        const size_t k_base = bh_base + (size_t)j * HEAD_DIM;
        float partial = 0.0f;
        for (int d = tid; d < HEAD_DIM; d += THREADS) {
            partial += q_sh[d] * __half2float(K[k_base + d]);
        }
        red[tid] = partial;
        __syncthreads();

        for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
            if (tid < offset) red[tid] += red[tid + offset];
            __syncthreads();
        }

        if (tid == 0) scores[j] = red[0] * scale;
        __syncthreads();
    }

    // Softmax over SEQ_LEN scores.
    if (tid < SEQ_LEN) red[tid] = scores[tid];
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) red[tid] = fmaxf(red[tid], red[tid + offset]);
        __syncthreads();
    }
    if (tid == 0) m_sh = red[0];
    __syncthreads();

    if (tid < SEQ_LEN) {
        scores[tid] = expf(scores[tid] - m_sh);
        red[tid] = scores[tid];
    }
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) red[tid] += red[tid + offset];
        __syncthreads();
    }
    if (tid == 0) sum_sh = red[0];
    __syncthreads();

    if (tid < SEQ_LEN) scores[tid] /= sum_sh;
    __syncthreads();

    // Weighted sum of values.
    for (int j = 0; j < SEQ_LEN; ++j) {
        const float p = scores[j];
        const size_t v_base = bh_base + (size_t)j * HEAD_DIM;
        for (int d = tid; d < HEAD_DIM; d += THREADS) {
            out_sh[d] += p * __half2float(V[v_base + d]);
        }
    }

    for (int d = tid; d < HEAD_DIM; d += THREADS) {
        O[q_base + d] = __float2half(out_sh[d]);
    }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have identical shapes");
    TORCH_CHECK(Q.size(0) == BATCH_SIZE && Q.size(1) == NUM_HEADS &&
                Q.size(2) == SEQ_LEN && Q.size(3) == HEAD_DIM,
                "Expected shape (2, 32, 256, 1024)");

    auto q = Q.contiguous();
    auto k = K.contiguous();
    auto v = V.contiguous();
    auto out = at::empty_like(q);

    dim3 grid(BATCH_SIZE * NUM_HEADS, SEQ_LEN);
    dim3 block(THREADS);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    sdpa_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(q.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(k.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(v.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(out.data_ptr<at::Half>())
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return out;
}
"""

_sdpa_ext = load_inline(
    name="custom_sdpa_single_kernel",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _sdpa_ext.sdpa_forward(Q, K, V)

